// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        // jojoTeam is set to the deployer (address(this)) at construction;
        // only a call from jojoTeam is admissible.
        vm.prank(address(this));
        c.newEmergencyOracle(description);

        // PREDICT the CREATE address of the freshly deployed oracle:
        // address(c) with nonce 1 at the time of deployment.
        bytes memory rlp = hex"d694";
        for (uint256 i = 0; i < 20; i++) {
            rlp.push(bytes20(address(c))[i]);
        }
        rlp.push(0x01); // nonce = 1
        address predicted = address(uint160(uint256(keccak256(rlp))));

        // read owner() of the deployed oracle through its public surface
        (bool ok, bytes memory data) = predicted.call(abi.encodeWithSignature("owner()"));
        assertTrue(ok && abi.decode(data, (address)) == actor);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface OracleView {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, string memory description) public {
        // The caller must be an admissible actor distinct from the freshly deployed c.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Drive c through its only external entry point.
        vm.prank(actor);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // The oracle created by c is deterministically address(keccak(rlp([c, nonce=1]))).
            // rlp for a 20-byte address and scalar nonce 1: 0xd6 0x94 <20 bytes> 0x01
            address predicted = address(
                uint160(uint256(keccak256(abi.encodePacked(hex"d694", bytes20(address(c)), hex"01"))))
            );
            // GENERAL RULE: any oracle c deploys on behalf of a caller is owned by that caller.
            assertTrue(OracleView(predicted).owner() == actor);
        } else {
            // Call rejected by c's own access control: the rule holds vacuously for this input.
            assertTrue(true);
        }
    }
}

