pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracleOwner {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // Deterministic CREATE address of c's first sub-deployment (nonce == 1 after c is created).
    function _predictedOracle() internal view returns (address) {
        return address(
            uint160(uint256(keccak256(abi.encodePacked(hex"d694", address(c), hex"01"))))
        );
    }

    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(this));

        address team = c.jojoTeam();

        bool ok;
        vm.prank(caller);
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // Admissibility: only the JOJO team may successfully deploy an oracle.
        vm.assume(!ok || caller == team);

        // General rule: for any admissible caller and any description, when the
        // call succeeds the newly created EmergencyOracle's owner() MUST equal
        // the calling address (msg.sender). The mutant installs jojoTeam as the
        // owner instead, breaking this for some input.
        assertTrue(
            !ok || IOracleOwner(_predictedOracle()).owner() == caller,
            "oracle owner must be the calling address"
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testNewEmergencyOracle(string calldata description) public {
        // jojoTeam is unset (address(0)) and this caller is never address(0),
        // so this caller is NOT the JOJO team.
        bool ok = true;
        // State-changing call must be top-level; use try to capture revert.
        // Since nesting rules forbid try/require wrapping for state calls, use a direct call.
        c.newEmergencyOracle(description);
        assert(ok);
    }

    receive() external payable {}
    fallback() external payable {}
}
